func EnsureDefaultMasterConnection(ctx context.Context, db *gorm.DB, cfg config.DBConfig, logger *zap.Logger) error {
	host := strings.TrimSpace(os.Getenv("CMS_MASTER_DB_HOST"))
	if host == "" {
		host = strings.TrimSpace(os.Getenv("CDS_MASTER_DB_HOST"))
	}
	if host == "" {
		host = strings.TrimSpace(cfg.Host)
	}
	port := cfg.Port
	if pStr := strings.TrimSpace(os.Getenv("CMS_MASTER_DB_PORT")); pStr != "" {
		if p, err := strconv.Atoi(pStr); err == nil && p > 0 {
			port = p
		}
	} else if pStr := strings.TrimSpace(os.Getenv("CDS_MASTER_DB_PORT")); pStr != "" {
		if p, err := strconv.Atoi(pStr); err == nil && p > 0 {
			port = p
		}
	}
	database := strings.TrimSpace(os.Getenv("CMS_MASTER_DB_DATABASE"))
	if database == "" {
		database = strings.TrimSpace(os.Getenv("CDS_MASTER_DB_NAME"))
	}
	if database == "" {
		database = strings.TrimSpace(cfg.Database)
	}

	err := db.WithContext(ctx).Exec(`
		INSERT INTO cdc_system.connection_registry
			(connection_code, display_name, role_type, engine_type,
			 host, port, default_database, secret_ref, status)
		VALUES ('default_master', 'Default Master Connection',
		        'master', 'postgresql',
		        NULLIF(?, ''), NULLIF(?, 0), NULLIF(?, ''), 'env:CDS_MASTER_DB_PASSWORD', 'active')
		ON CONFLICT (connection_code) DO UPDATE
		   SET host             = COALESCE(NULLIF(EXCLUDED.host, ''), cdc_system.connection_registry.host),
		       port             = COALESCE(EXCLUDED.port, cdc_system.connection_registry.port),
		       default_database = COALESCE(NULLIF(EXCLUDED.default_database, ''), cdc_system.connection_registry.default_database),
		       status           = 'active',
		       updated_at       = NOW()
	`, host, port, database).Error

